-- ops Step 4a — core.equipment_models (canonical equipment identity; SSoT Law 5)
-- Lane SSoT:  reference/ops/00-MASTER-INDEX.md      Spec: docs/spec/ESTIMATOR_SPEC_2026-06-22.md §2/§9
-- Dev DB:     ops_dev (local PG). Nothing applied to prod.
-- Seed:       008_equipment_models.seed.json (estimator-core; sha256 dfe59bc3…, 120 active rows)
-- Co-location: hardens ops.apparatus.equipment_model_ref (mig 001:152 soft seam) to a real FK.
-- ============================================================================

create schema if not exists core;

create type core.equipment_lifecycle as enum ('active','deprecated','merged');
create type core.unit_of_issue       as enum ('each','set');

create table core.equipment_models (
  id               uuid primary key default gen_random_uuid(),
  model_key        text not null unique,            -- stable natural identity (estimator-core `ref`)
  apparatus        text not null,                   -- Scope of Work (tblEquipment apparatus)
  neta_section_ats text,
  neta_section_mts text,
  ref_hours_ats    numeric,
  ref_hours_mts    numeric,
  unit_of_issue    core.unit_of_issue       not null,
  lifecycle_status core.equipment_lifecycle not null default 'active',
  merged_into_id   uuid references core.equipment_models(id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint equipment_models_merge_chk check (
    (lifecycle_status = 'merged') = (merged_into_id is not null)   -- merged <=> points somewhere
  ),
  constraint equipment_models_no_self_merge_chk check (
    merged_into_id is distinct from id                            -- forbid a 1-cycle (review nit)
  )
);
comment on table core.equipment_models is
  'Canonical equipment identity (SSoT Law 5). Seeded 1:1 (active dimension) from estimator-core equipment-models.seed.json (sha256 dfe59bc3, 120 rows). Reads via core.v_equipment_models_resolved (cycle-safe merge-chasing). ops.apparatus.equipment_model_ref FKs id.';

-- cycle-safe merge-chasing resolver: every origin -> its terminal ACTIVE identity (spec §2 "to the
-- active identity"). Enterable by id OR model_key (4b binds by the estimator string ref). Resolves
-- to a row IFF the chain ends at an ACTIVE, non-merged identity; a cycle, a merged->deprecated
-- chain, or a deprecated leaf resolves to NO row (detectable -> 4b rejects / routes to catalog_requests).
create or replace view core.v_equipment_models_resolved as
with recursive chase as (
  select id as origin_id, model_key as origin_model_key,
         id as cur_id, merged_into_id, array[id] as path
  from core.equipment_models
  union all
  select c.origin_id, c.origin_model_key, m.id, m.merged_into_id, c.path || m.id
  from chase c
  join core.equipment_models m on m.id = c.merged_into_id
  where m.id <> all(c.path)                 -- never revisit a node (terminates any cycle)
)
select
  c.origin_id        as requested_id,
  c.origin_model_key as requested_model_key, -- 4b enters by the estimator string ref
  t.id               as resolved_id,         -- the terminal active identity
  t.model_key        as resolved_model_key,
  t.apparatus, t.neta_section_ats, t.neta_section_mts,
  t.ref_hours_ats, t.ref_hours_mts, t.unit_of_issue, t.lifecycle_status
from chase c
join core.equipment_models t on t.id = c.cur_id
where t.merged_into_id is null              -- structural terminal
  and t.lifecycle_status = 'active';        -- ACTIVE terminal only (spec §2); else NO row (detectable)

